<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppModal from '@/components/AppModal.vue'
import AppIcon from '@/components/AppIcon.vue'
import ApiWorkspace from '@/components/ApiWorkspace.vue'
import { accountState } from '@/services/officine'
import SidebarNavigation from '@/components/SidebarNavigation.vue'
import { navigation, plannedTitle } from '@/config/navigation'
import { demoMode, request } from '@/services/quality'
import AppToast from '@/components/AppToast.vue'
import { clearToasts } from '@/services/notify'
import { currentOffice, supportState } from '@/services/supportDemo'
const demoProfile=computed(()=>supportState.persona==='company'?'Coordination entreprise':'Administrateur officine')
const route=useRoute();const router=useRouter();const menu=ref(false)
let stored=false;try{stored=localStorage.getItem('bestpharma.sidebar.collapsed')==='true'}catch{/* optional preference */}
const collapsed=ref(stored);const searchOpen=ref(false);const search=ref('')
const publicPage=computed(()=>route.meta.public)
const canReview=computed(()=>{void route.path;return demoMode||sessionStorage.getItem('bestpharma.platform')==='true'})
const pageTitle=computed(()=>route.meta.title==='Module prévu'?plannedTitle(route.fullPath):route.meta.title)
const results=computed(()=>navigation.flatMap(g=>g.children.map(c=>({...c,group:g.label}))).filter(c=>c.label.toLocaleLowerCase('fr').includes(search.value.toLocaleLowerCase('fr'))))
function toggleCollapse(){collapsed.value=!collapsed.value;try{localStorage.setItem('bestpharma.sidebar.collapsed',String(collapsed.value))}catch{/* optional preference */}}
async function logout(){try{if(!demoMode)await request('/auth/logout','POST')}finally{accountState.user=null;accountState.officines=[];sessionStorage.removeItem('bestpharma.token');sessionStorage.removeItem('bestpharma.officine');sessionStorage.removeItem('bestpharma.platform');router.push('/login')}}
watch(() => route.path, () => clearToasts())
</script>
<template><RouterView v-if="publicPage"/><div v-else class="app-shell erp-shell" :class="{'sidebar-collapsed':collapsed}"><a class="skip-link" href="#main">Aller au contenu</a><aside class="sidebar" :class="{expanded:menu}"><div class="sidebar-brand"><RouterLink to="/dashboard" class="brand" @click="menu=false"><span class="brand-mark">b<span>+</span></span><span class="brand-word">bestpharma<span class="brand-dot">.</span></span></RouterLink><button class="icon-button collapse-control" :aria-label="collapsed?'Déplier la barre latérale':'Replier la barre latérale'" :aria-expanded="!collapsed" @click="toggleCollapse"><AppIcon name="chevron" :size="15" :style="{transform:collapsed?'':'rotate(180deg)'}"/></button></div>
<ApiWorkspace v-if="!demoMode"/><RouterLink v-else to="/dashboard/officine" class="workspace" :title="currentOffice.name+' · '+currentOffice.city" @click="menu=false"><div class="workspace-avatar">BP</div><div class="workspace-copy"><strong>{{currentOffice.name}}</strong><small>{{currentOffice.city}} · Démonstration</small></div><AppIcon name="chevron" :size="13"/></RouterLink>
<SidebarNavigation :collapsed="collapsed&&!menu" @navigate="menu=false" @expand="collapsed=false"/>
<div class="sidebar-admin"><RouterLink v-if="!demoMode&&accountState.user?.is_support_coordinator" class="nav-item" to="/beg/demandes-accompagnement" title="Guichet accompagnement" @click="menu=false"><AppIcon name="support" :size="17"/><span>Guichet accompagnement</span></RouterLink><RouterLink v-if="!demoMode" class="nav-item" to="/dashboard/acces" title="Tableau des accès"><AppIcon name="team" :size="17"/><span>Tableau des accès</span></RouterLink><RouterLink v-if="canReview&&!demoMode" class="nav-item" to="/beg/synthese" title="Synthèse plateforme"><AppIcon name="quality" :size="17"/><span>Synthèse plateforme</span></RouterLink><RouterLink v-if="canReview&&!demoMode" class="nav-item" to="/beg/comptes" title="État des comptes"><AppIcon name="team" :size="17"/><span>État des comptes</span></RouterLink><RouterLink v-if="canReview&&!demoMode" class="nav-item" to="/beg/equipe-interne" title="Équipe interne"><AppIcon name="team" :size="17"/><span>Équipe d’accompagnement</span></RouterLink><RouterLink v-if="canReview&&!demoMode" class="nav-item" to="/beg/officines" title="États des officines"><AppIcon name="settings" :size="17"/><span>États des officines</span></RouterLink><RouterLink v-if="!demoMode&&accountState.user?.is_support_coordinator" class="nav-item" to="/beg/accompagnateurs" title="Coordination des accès" @click="menu=false"><AppIcon name="support" :size="17"/><span>Coordination des accès</span></RouterLink><RouterLink to="/application" class="nav-item" title="Mon dossier d’ouverture" @click="menu=false"><AppIcon name="documents" :size="17"/><span>Mon dossier d’ouverture</span></RouterLink><RouterLink v-if="canReview" to="/beg/inscriptions" class="nav-item" title="Instruction BEG" @click="menu=false"><AppIcon name="quality" :size="17"/><span>Instruction BEG</span></RouterLink></div>
<div class="sidebar-bottom"><button class="profile" @click="logout" title="Quitter la session"><span class="profile-avatar">{{demoMode?'D':'M'}}</span><span class="profile-copy"><strong>{{demoMode?demoProfile:'Mon compte'}}</strong><small>{{demoMode?'Profil démo · Quitter':'Quitter la session'}}</small></span><AppIcon name="logout" :size="16"/></button></div></aside>
<button v-if="menu" class="menu-overlay" aria-label="Fermer le menu" @click="menu=false"/>
<div class="workspace-main"><header class="topbar"><div class="topbar-left"><button class="icon-button mobile-menu" aria-label="Ouvrir le menu" :aria-expanded="menu" @click="menu=!menu"><AppIcon name="menu"/></button><span class="breadcrumb-root">Espace officine</span><AppIcon class="breadcrumb-root" name="chevron" :size="12"/><strong>{{pageTitle}}</strong></div><div class="topbar-right"><RouterLink v-if="!demoMode" to="/notifications" class="icon-button" aria-label="Notifications"><AppIcon name="info" :size="17"/></RouterLink><button class="header-search" aria-label="Rechercher un espace" @click="search='';searchOpen=true"><AppIcon name="search" :size="16"/><span>Rechercher un espace…</span></button><span class="environment" :class="{'demo-environment':demoMode}"><i/>{{demoMode?'Démonstration':'Connecté'}}</span><RouterLink to="/dashboard/profil" class="top-avatar" :aria-label="demoMode?'Profil démo : '+demoProfile:'Mon profil'">{{demoMode?'D':'M'}}</RouterLink></div></header>
<main id="main" tabindex="-1"><RouterView/></main><footer>BestPharma · L’officine, accompagnée.</footer></div></div>
<AppModal v-model="searchOpen" title="Rechercher un espace"><div class="form-body"><label class="search-field"><AppIcon name="search" :size="17"/><input v-model="search" placeholder="Ex. accompagnement, stock…" aria-label="Rechercher un espace"/></label><ul class="search-results"><li v-for="r in results" :key="r.to"><RouterLink :to="r.to" @click="searchOpen=false"><span>{{r.label}}<small>{{r.group}}</small></span><span v-if="r.planned" class="module-chip">À venir</span><AppIcon v-else name="chevron" :size="14"/></RouterLink></li></ul><p v-if="!results.length" class="empty-state">Aucun espace correspondant.</p></div></AppModal><AppToast /></template>
